import re,json
import xml.etree.ElementTree as ET
from pathlib import Path
ROOT=Path(__file__).parent
NOTICE='''<aside class="garage-notice"><h2>Independent owners. Direct enquiries.</h2><p>Owner’s Garage is an advertising service only. Enquiries, bookings, hire agreements and payments are arranged directly with the vehicle owner. The owner is responsible for vehicle condition, safety, insurance, listing accuracy, cancellations, refunds and booking disputes. Lakeland Touring does not inspect or guarantee independently advertised vehicles and is not a party to their hire agreements.</p><p>This does not affect your statutory rights or our responsibility for our own advertising service. We do not exclude liability that cannot lawfully be excluded. Our own Elddis hire service has separate booking terms.</p></aside>'''
def links(s):
 if 'owners-garage.html' not in s:
  s=s.replace('</nav>','<a href="garage.php?view=browse">Owner vehicles</a><a href="owners-garage.html">Owner’s Garage</a></nav>',1)
  s=s.replace('<h3>Explore</h3>','<h3>Explore</h3><a href="owners-garage.html">Advertise your vehicle</a><a href="garage.php">Owner sign in</a><a href="owner-terms.html">Owner advertising terms</a>',1)
 return s

def build(index,booking,sitemap=None,robots=None):
 header=links(re.search(r'<header\b[\s\S]*?</header>',index).group()).replace('href="#','href="index.html#')
 footer=links(re.search(r'<footer\b[\s\S]*?</footer>',index).group())
 def page(title,description,path,body):
  schema={'@context':'https://schema.org','@type':'WebPage','name':title,'url':'https://lakelandtouring.uk/'+path,'description':description,'isPartOf':{'@type':'WebSite','name':'Lakeland Touring','url':'https://lakelandtouring.uk/'}}
  return '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+title+' | Lakeland Touring</title><meta name="description" content="'+description+'"><link rel="canonical" href="https://lakelandtouring.uk/'+path+'"><meta name="robots" content="index,follow,max-image-preview:large"><meta property="og:type" content="website"><meta property="og:site_name" content="Lakeland Touring"><meta property="og:title" content="'+title+'"><meta property="og:description" content="'+description+'"><meta property="og:url" content="https://lakelandtouring.uk/'+path+'"><meta property="og:image" content="https://lakelandtouring.uk/Assets/lakeland-touring-official.png"><meta name="twitter:card" content="summary_large_image"><link rel="stylesheet" href="styles.css"><link rel="stylesheet" href="brand.css?v=20261015-centre3"><link rel="stylesheet" href="garage.css?v=1"><script type="application/ld+json">'+json.dumps(schema)+'</script></head><body>'+header+'<main class="garage-main">'+body+'</main>'+footer+'</body></html>'
 landing='''<span class="eyebrow">OWNER’S GARAGE</span><h1>Your vehicle.<br><em>Your own garage.</em></h1><p>Advertise your caravan, motorhome or campervan on Lakeland Touring. Your own login, your own listing, and enquiries straight to you.</p><div class="garage-layout"><section class="garage-box"><h2>Simple annual advertising.</h2><strong class="price">£49</strong><p>Per vehicle · 12 months from activation<br>No booking commission · No automatic renewal</p><a class="button" href="garage.php">Create your garage / sign in →</a><p>Prepare your draft free. We review the advert and arrange payment by invoice before publication. Your annual term begins when the listing is activated.</p></section><section class="garage-box"><h2>You stay in control.</h2><ol><li>Create your account and verify your email.</li><li>Add your vehicle details, hire prices and up to 12 photos.</li><li>Request review and pay your annual invoice.</li><li>Receive enquiries directly and manage your own bookings.</li></ol><p>Edit your advert from your garage. Changes are reviewed before republication. Expired listings come offline until renewed.</p><a href="garage.php?view=browse">Browse owner vehicles →</a></section></div>'''+NOTICE+'''<h2>Have a question before joining?</h2><p><a href="mailto:LakelandTouring@Worx365Group.uk?subject=Owner%27s%20Garage%20enquiry">LakelandTouring@Worx365Group.uk</a> · <a href="tel:+441228307953">01228 307953</a></p><p><a href="owner-terms.html">Owner advertising terms</a> · <a href="garage-privacy.html">Garage privacy notice</a></p>'''
 terms='''<span class="eyebrow">OWNER’S GARAGE</span><h1>Owner advertising terms</h1><p>Effective 15 October 2026. These terms cover independent owner advertisements on Lakeland Touring, part of Worx365 Group, Carlisle, Cumbria. Contact: LakelandTouring@Worx365Group.uk · 01228 307953.</p><h2>The advertising service</h2><p>£49 buys one approved vehicle advertisement for 12 months from activation. You may create an account and prepare a draft without payment. We review the advert and arrange an invoice before activation. There is no booking commission or automatic renewal. No payment is taken through the garage. The invoiced total for one annual advert is £49, with no further platform charge.</p><h2>Your responsibilities</h2><p>You must own the vehicle or have authority to advertise it. Give accurate details, genuine photographs you have permission to use, clear hire prices and your correct contact details. State whether you act as a business or private owner and provide prospective hirers with your identity, applicable hire terms and any legally required business information before a booking.</p><p>You are responsible for the vehicle’s condition, safety, maintenance, roadworthiness where applicable, suitability for hire, required licences, insurance and any legal requirements that apply to your hire activity. You manage availability, bookings, agreements, deposits, payments, handovers, cancellations, refunds and disputes directly with hirers. Do not advertise a vehicle unless it can lawfully be hired.</p><h2>Review, updates and expiry</h2><p>We check adverts before publication, but this is not an inspection or safety certification. Changes return a listing to draft for review; its existing paid expiry date does not change. We may ask for ownership evidence, correct misleading content, or remove unlawful or inaccurate adverts. You can keep your listing offline from your garage. We do not guarantee enquiries, bookings, income or search rankings. Expired adverts are removed from public view until renewed. We do not renew or charge automatically.</p><h2>Cancellation and problems with our service</h2><p>Contact us before activation if you wish to cancel; an unactivated annual advert will be refunded. If you buy as a consumer and have a statutory cancellation right, that right continues to apply. Contact us about a problem with our advertising service so we can investigate and provide an appropriate remedy. Nothing here removes your statutory rights.</p>'''+NOTICE+'''<h2>Reporting an advert</h2><p>Send the listing title or link and your concerns to <a href="mailto:LakelandTouring@Worx365Group.uk">our team</a>. We can review or remove an advert, but hire complaints must be raised with the owner who supplies the vehicle.</p>'''
 privacy='''<span class="eyebrow">OWNER’S GARAGE</span><h1>Garage privacy notice</h1><p>Lakeland Touring, part of Worx365 Group, uses your information to provide and administer Owner’s Garage. Contact LakelandTouring@Worx365Group.uk or 01228 307953 about your data.</p><h2>What we store and why</h2><p>We store your name, email address, a securely hashed password, email verification and reset records, vehicle details, uploaded photos, listing status and annual expiry. We use these to administer your account and advertising agreement. Short-lived sign-in attempt records help protect accounts against abuse. Our legal bases are performance of your advertising agreement and our legitimate interest in keeping the service secure.</p><h2>What becomes public</h2><p>Approved, paid listings display the vehicle details, location, hire price, photos and the public enquiry email you enter. Your login password and account verification records are never public. Only upload information and photos you are entitled to publish. Enquiries go directly to your advertised email; we do not process hire payments through Owner’s Garage.</p><h2>Service providers and cookies</h2><p>Our hosting and email providers process the information needed to deliver the service. A necessary secure session cookie keeps you signed in and protects form submissions. We do not use garage account details for advertising tracking or sell them to other advertisers.</p><h2>Retention and your rights</h2><p>We retain account and listing data while you use the service. Contact us to close your account and request deletion; we remove listings and account data unless records must be kept for legal, accounting or dispute purposes. Verification and password reset links expire after one hour. You can request access, correction, erasure or restriction and exercise other applicable data protection rights. You may also complain to the Information Commissioner’s Office at <a href="https://ico.org.uk/">ico.org.uk</a>.</p>'''
 out={'owners-garage.html':page('Advertise Your Caravan or Motorhome — Owner’s Garage','Advertise your caravan, motorhome or campervan for £49 per vehicle per year. Your own garage login, photos and direct owner enquiries. No booking commission.','owners-garage.html',landing),'owner-terms.html':page('Owner Advertising Terms','Read the annual advertising terms and vehicle owner responsibilities for Lakeland Touring Owner’s Garage.','owner-terms.html',terms),'garage-privacy.html':page('Owner’s Garage Privacy Notice','How Lakeland Touring handles owner account information, vehicle listings, photos and direct enquiry details.','garage-privacy.html',privacy),'garage-header.html':header,'garage-footer.html':footer}
 # New-plan pages are separate from legacy terms until an owner explicitly accepts.
 out['owner-booking-terms.html']=page('Owner Booking Plan','£49 annual advertising per vehicle plus a £25 admin fee per confirmed booking.','owner-booking-terms.html',ROOT.joinpath('booking-terms.html').read_text())
 out['garage-booking-privacy.html']=page('Owner Booking Privacy','How owner booking and payment confirmation records are handled.','garage-booking-privacy.html',ROOT.joinpath('booking-privacy.html').read_text())
 out['garage-bookings.php']=ROOT.joinpath('bookings.php').read_text()
 out['garage-bookings-ui.php']=ROOT.joinpath('bookings-ui.php').read_text()
 out['booking-policy.php']=ROOT.parent.joinpath('booking-backend/operations.php').read_text()
 for name,s in [('index.html',index),('booking.html',booking)]:
  s=links(s)
  if name=='index.html' and 'id="owners"' not in s:s=s.replace('<section class="final-cta">','<section id="owners" class="editorial"><span class="eyebrow">FOR VEHICLE OWNERS</span><h2>Your vehicle. <em>Your own garage.</em></h2><p>Advertise your caravan, motorhome or campervan for £49 per vehicle per year. Upload photos, manage your listing and receive enquiries directly. No booking commission.</p><a class="button" href="owners-garage.html">Explore Owner’s Garage →</a></section><section class="final-cta">')
  # Complete social metadata without altering the existing booking functionality.
  if 'name="twitter:image"' not in s:s=s.replace('</head>','<meta name="twitter:image" content="https://lakelandtouring.uk/Assets/buttermere-4k.jpg"><meta property="og:image:alt" content="Buttermere in the Lake District"></head>')
  out[name]=s
 out['robots.txt']=robots if robots is not None else 'User-agent: *\nAllow: /\nDisallow: /Admin/\nDisallow: /Api/\nDisallow: /Data/\nDisallow: /config.php\nDisallow: /webhook.php\nDisallow: /success.php\nSitemap: https://lakelandtouring.uk/sitemap.xml\n'
 pages=['','booking.html','owners-garage.html','owner-terms.html','garage-privacy.html','owner-booking-terms.html','garage-booking-privacy.html','garage.php?view=browse']
 out['sitemap.xml']='<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join('<url><loc>https://lakelandtouring.uk/'+p+'</loc></url>' for p in pages)+'</urlset>\n'
 if sitemap is not None:
  namespace='http://www.sitemaps.org/schemas/sitemap/0.9'
  ET.register_namespace('',namespace)
  tree=ET.fromstring(sitemap)
  if tree.tag!='{'+namespace+'}urlset':raise ValueError('Expected an existing URL sitemap')
  existing={item.text for item in tree.findall('{'+namespace+'}url/{'+namespace+'}loc')}
  for path in pages:
   url='https://lakelandtouring.uk/'+path
   if url not in existing:ET.SubElement(ET.SubElement(tree,'{'+namespace+'}url'),'{'+namespace+'}loc').text=url
  out['sitemap.xml']='<?xml version="1.0" encoding="UTF-8"?>\n'+ET.tostring(tree,encoding='unicode')+'\n'
 for name in ['garage.php','garage.css']:out[name]=(ROOT/name).read_text()
 return out
